 15→use std::collections::HashMap;
 16→use std::time::Duration;
 17→
 18→use async_trait::async_trait;
 19→use spice_cloud_client::CloudClient;
 20→use system_adapter_protocol::{
 21→    AdbcDriver, DatasetConfig, Handler, IngestionMetrics, MetricsResponse, ResourceMetrics, Server,
 22→    SetupResponse, TeardownResponse,
 23→};
 24→use test_framework::anyhow;
 25→use uuid::Uuid;
 26→
 27→use crate::args::StdioArgs;
 28→use crate::commands;
 29→
 30→/// State for an active benchmark run provisioned via `setup`.
 31→struct RunState {
 32→    /// Spice Cloud app ID.
 33→    app_id: i64,
 34→    /// API key for the app (used for Flight SQL authentication).
 35→    api_key: String,
 36→    /// Flight SQL endpoint URL derived from the cname.
 37→    flight_url: String,
 38→    /// Cloud client used during provisioning (reused for teardown).
 39→    cloud: CloudClient,
 40→}
 41→
 42→#[derive(Debug, Clone)]
 43→struct SetupConfig {
 44→    /// Per-dataset `from` URIs, keyed by dataset name.
 45→    etl_region: Option<String>,
 46→    etl_endpoint: Option<String>,
 47→}
 48→
 49→impl SetupConfig {
 50→    fn from_metadata(metadata: &HashMap<String, serde_json::Value>) -> anyhow::Result<Self> {
 51→        Ok(Self {
 52→            etl_region: metadata_string(metadata, "etl_region"),
 53→            etl_endpoint: metadata_string(metadata, "etl_endpoint"),
 54→        })
 55→    }
 56→}
 57→
 58→fn metadata_string(metadata: &HashMap<String, serde_json::Value>, key: &str) -> Option<String> {
 59→    metadata
 60→        .get(key)
 61→        .and_then(serde_json::Value::as_str)
 62→        .map(str::trim)
 63→        .filter(|s| !s.is_empty())
 64→        .map(ToString::to_string)
 65→}
 66→
 67→/// System adapter handler that provisions Spice Cloud apps.
 68→struct SpidapterHandler {
 69→    /// Active runs keyed by run ID.
 70→    runs: HashMap<Uuid, RunState>,
 71→    /// Spice Cloud API URL override (from CLI args).
 72→    api_url_override: Option<String>,
 73→    /// Timeout in seconds for deployment readiness.
 74→    ready_wait: u64,
 75→    /// Release channel for the spice.ai runtime image.
 76→    channel: Option<String>,
 77→}
 78→
 79→impl SpidapterHandler {
 80→    fn new(args: &StdioArgs) -> Self {
 81→        Self {
 82→            runs: HashMap::new(),
 83→            api_url_override: args.spice_cloud_api_url.clone(),
 84→            ready_wait: args.ready_wait,
 85→            channel: args.channel.clone(),
 86→        }
 87→    }
 88→}
 89→
 90→#[async_trait]
 91→impl Handler for SpidapterHandler {
 92→    async fn setup(
 93→        &mut self,
 94→        run_id: Uuid,
 95→        metadata: HashMap<String, serde_json::Value>,
 96→        datasets: HashMap<String, DatasetConfig>,
 97→    ) -> Result<SetupResponse, String> {
 98→        eprintln!(
 99→            "[stdio] setup: run_id={run_id}, metadata_keys={:?}",
100→            metadata.keys().collect::<Vec<_>>()
101→        );
102→
103→        let setup_config = SetupConfig::from_metadata(&metadata)
104→            .map_err(|e| format!("Invalid setup metadata: {e}"))?;
105→
106→        let state = provision_spice_cloud_app(
107→            run_id,
108→            self.api_url_override.as_deref(),
109→            self.ready_wait,
110→            self.channel.as_deref(),
111→            &setup_config,
112→            &datasets,
113→        )
114→        .await
115→        .map_err(|e| format!("Setup failed: {e}"))?;
116→
117→        let response = SetupResponse {
118→            driver: AdbcDriver::Flightsql,
119→            db_kwargs: HashMap::from([
120→                (
121→                    "uri".to_string(),
122→                    serde_json::Value::String(state.flight_url.clone()),
123→                ),
124→                (
125→                    "username".to_string(),
126→                    serde_json::Value::String(String::new()),
127→                ),
128→                (
129→                    "password".to_string(),
130→                    serde_json::Value::String(state.api_key.clone()),
131→                ),
132→            ]),
133→        };
134→
135→        self.runs.insert(run_id, state);
136→        Ok(response)
137→    }
138→
139→    async fn metrics(&mut self, run_id: Uuid) -> std::result::Result<MetricsResponse, String> {
140→        let state = self
141→            .runs
142→            .get(&run_id)
143→            .ok_or_else(|| format!("No active run found for {run_id}"))?;
144→
145→        let cloud_metrics = state
146→            .cloud
147→            .get_app_metrics(state.app_id)
148→            .await
149→            .map_err(|e| format!("Failed to fetch metrics: {e}"))?;
150→
151→        let pods = cloud_metrics.metrics.values().collect::<Vec<_>>();
152→
153→        let resource = if pods.is_empty() {
154→            ResourceMetrics::default()
155→        } else {
156→            let avg_cpu = match pods
157→                .iter()
158→                .filter_map(|p| p.cpu_usage_percent.is_some().then(|| 1.0))
159→                .sum::<f64>()
160→            {
161→                0.0 => None,
162→                n => Some(pods.iter().filter_map(|p| p.cpu_usage_percent).sum::<f64>() / n),
163→            };
164→
165→            let total_memory = match pods
166→                .iter()
167→                .filter_map(|p| p.memory_usage_bytes.is_some().then(|| 1))
168→                .sum::<u64>()
169→            {
170→                0 => None,
171→                n => Some(
172→                    pods.iter()
173→                        .filter_map(|p| p.memory_usage_bytes)
174→                        .sum::<u64>()
175→                        / n as u64,
176→                ),
177→            };
178→            ResourceMetrics {
179→                cpu_usage_percent: avg_cpu,
180→                memory_usage_bytes: total_memory,
181→                disk_read_bytes: None,
182→                disk_write_bytes: None,
183→                disk_read_iops: None,
184→                disk_write_iops: None,
185→            }
186→        };
187→
188→        let ingestion = cloud_metrics
189→            .ingestion
190→            .map(|i| IngestionMetrics {
191→                rows_ingested: i.rows_ingested,
192→                bytes_ingested: i.bytes_ingested,
193→                ..IngestionMetrics::default()
194→            })
195→            .unwrap_or_default();
196→
197→        Ok(MetricsResponse {
198→            resource,
199→            ingestion,
200→        })
201→    }
202→
203→    async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
204→        eprintln!("[stdio] teardown: run_id={run_id}");
205→
206→        let Some(state) = self.runs.remove(&run_id) else {
207→            eprintln!("[stdio] teardown: run_id={run_id} not found (already torn down?)");
208→            return Ok(TeardownResponse { ok: true });
209→        };
210→
211→        eprintln!(
212→            "[stdio] teardown: deleting app {} at {}",
213→            state.app_id,
214→            state.cloud.base_url()
215→        );
216→
217→        commands::delete_app(&state.cloud, state.app_id)
218→            .await
219→            .map_err(|e| format!("Failed to delete app {}: {e}", state.app_id))?;
220→
221→        eprintln!("[stdio] teardown: app {} deleted", state.app_id);
222→        Ok(TeardownResponse { ok: true })
223→    }
224→}
