226→pub async fn run_stdio_server(args: &StdioArgs) -> anyhow::Result<()> {
227→    let handler = SpidapterHandler::new(args);
228→    let mut server = Server::new(handler);
229→    server
230→        .run_stdio()
231→        .await
232→        .map_err(|e| anyhow::anyhow!("Stdio server error: {e}"))
233→}
