235→// ── Spice Cloud provisioning ─────────────────────────────────────────
236→
237→/// Provision a Spice Cloud app from the setup request.
238→///
239→/// Follows the same flow as `SpiceCloudSpicedStarter::start()`:
240→/// 1. Resolve the default cname / region
241→/// 2. Create or find the SCP app
242→/// 3. Generate and upload the spicepod from the dataset configs
243→/// 4. Set secrets (RUNNER + any env-based secrets)
244→/// 5. Create a deployment
245→/// 6. Wait for the deployment to become ready
246→async fn provision_spice_cloud_app(
247→    run_id: Uuid,
248→    api_url_override: Option<&str>,
249→    ready_wait: u64,
250→    channel: Option<&str>,
251→    setup_config: &SetupConfig,
252→    datasets: &HashMap<String, DatasetConfig>,
253→) -> anyhow::Result<RunState> {
254→    let cloud = commands::build_cloud_client(api_url_override)?;
255→
256→    let cname = commands::resolve_default_cname(&cloud).await?;
257→    let flight_url = commands::flight_url_from_cname(&cname);
258→    let run_id_str = run_id.to_string();
259→    let short_id = run_id_str.split('-').next().unwrap_or_default();
260→    let app_name = commands::sanitize_app_name(&format!("spidapter-{short_id}"));
261→
262→    eprintln!("[stdio] Spice Cloud API: {}", cloud.base_url());
263→    eprintln!("[stdio] Region cname: {cname}");
264→    eprintln!("[stdio] Flight endpoint: {flight_url}");
265→    eprintln!("[stdio] App name: {app_name}");
266→
267→    let (app_id, app_api_key) = commands::ensure_spice_cloud_app(&cloud, &app_name).await?;
268→
269→    let api_key = app_api_key.ok_or_else(|| {
270→        anyhow::anyhow!("Spice Cloud did not return an API key for app '{app_name}'")
271→    })?;
272→
273→    eprintln!("[stdio] App ID: {app_id}");
274→
275→    let spicepod_yaml = generate_initial_spicepod(&run_id, setup_config, datasets)?;
276→    eprintln!("[stdio] Generated spicepod:\n{spicepod_yaml}");
277→
278→    eprintln!("[stdio] Uploading spicepod to app...");
279→    commands::apply_spicepod_to_app(&cloud, app_id, &spicepod_yaml).await?;
280→    eprintln!("[stdio] Spicepod uploaded");
281→
282→    // Set secrets from environment for any secret references in the spicepod
283→    eprintln!("[stdio] Setting secrets from spicepod...");
284→    commands::secrets::set_spicepod_secrets(&cloud, app_id, &spicepod_yaml).await?;
285→    eprintln!("[stdio] Spicepod secrets set");
286→
287→    eprintln!("[stdio] Setting RUNNER secret...");
288→    commands::secrets::set_secret(&cloud, app_id, "RUNNER", "spidapter").await?;
289→    eprintln!("[stdio] RUNNER secret set");
290→
291→    eprintln!("[stdio] Creating deployment...");
292→    commands::create_deployment(&cloud, app_id, channel).await?;
293→
294→    let poll_client = reqwest::Client::builder()
295→        .timeout(Duration::from_secs(600))
296→        .build()?;
297→    commands::wait_for_deployment_ready(
298→        &poll_client,
299→        &cname,
300→        &api_key,
301→        Duration::from_secs(ready_wait),
302→    )
303→    .await?;
304→
305→    eprintln!("[stdio] Spice Cloud deployment ready for app '{app_name}' at {flight_url}");
306→
307→    Ok(RunState {
308→        app_id,
309→        api_key,
310→        flight_url,
311→        cloud,
312→    })
313→}
