315→/// Generate the spicepod YAML with individual dataset entries sourced from S3 parquet files.
316→fn generate_initial_spicepod(
317→    run_id: &Uuid,
318→    setup_config: &SetupConfig,
319→    datasets: &HashMap<String, DatasetConfig>,
320→) -> anyhow::Result<String> {
321→    let run_id_str = run_id.to_string();
322→    let short_id = run_id_str.split('-').next().unwrap_or_default();
323→    let region = setup_config
324→        .etl_region
325→        .clone()
326→        .or_else(|| std::env::var("AWS_REGION").ok())
327→        .or_else(|| std::env::var("AWS_DEFAULT_REGION").ok())
328→        .unwrap_or_else(|| "us-east-1".to_string());
329→
330→    let mut dataset_entries = Vec::new();
331→    for d in datasets {
332→        match d {
333→            (
334→                dataset_name,
335→                DatasetConfig {
336→                    location: Some(from),
337→                    ..
338→                },
339→            ) => {
340→                let mut params = vec![
341→                    "      file_format: parquet".to_string(),
342→                    "      s3_auth: public".to_string(),
343→                    format!("      s3_region: {region}"),
344→                ];
345→
346→                if let Some(endpoint) = &setup_config.etl_endpoint {
347→                    params.push(format!("      s3_endpoint: {endpoint}"));
348→                }
349→
350→                dataset_entries.push(format!(
351→                    "  - from: {from}\n    \
352→                    name: {dataset_name}\n    \
353→                    params:\n{}\n    \
354→                    acceleration:\n      \
355→                    enabled: true\n      \
356→                    engine: cayenne\n      \
357→                    mode: file\n      \
358→                    refresh_mode: full\n      \
359→                    refresh_check_interval: 1s",
360→                    params.join("\n")
361→                ));
362→            }
363→            (dataset_name, _) => {
364→                return Err(anyhow::anyhow!(
365→                    "Dataset '{dataset_name}' is missing a 'from' URI in its config"
366→                ));
367→            }
368→        }
369→    }
370→
371→    Ok(format!(
372→        "version: v1beta1\n\
373→         kind: Spicepod\n\
374→         name: spidapter-{short_id}\n\
375→         \n\
376→         datasets:\n{}\n",
377→        dataset_entries.join("\n")
378→    ))
379→}
