381→#[cfg(test)]
382→mod tests {
383→    use super::*;
384→    use arrow::datatypes::{DataType, Field, Schema};
385→    use std::sync::Arc;
386→
387→    #[test]
388→    fn setup_config_parses_dataset_sources_from_metadata() {
389→        let metadata = HashMap::from([
390→            (
391→                "my_table".to_string(),
392→                serde_json::json!({"from": "s3://bucket/path/my_table/"}),
393→            ),
394→            (
395→                "etl_region".to_string(),
396→                serde_json::Value::String("us-west-2".to_string()),
397→            ),
398→        ]);
399→
400→        let config = SetupConfig::from_metadata(&metadata).expect("metadata should parse");
401→        assert_eq!(
402→            config.dataset_sources.get("my_table").unwrap(),
403→            "s3://bucket/path/my_table/"
404→        );
405→        assert_eq!(config.etl_region.as_deref(), Some("us-west-2"));
406→    }
407→
408→    #[test]
409→    fn generate_spicepod_includes_dataset_entries() {
410→        let setup_config = SetupConfig {
411→            dataset_sources: HashMap::from([(
412→                "my_table".to_string(),
413→                "s3://bucket/path/my_table/".to_string(),
414→            )]),
415→            etl_region: Some("us-west-2".to_string()),
416→            etl_endpoint: Some("http://localhost:9000".to_string()),
417→        };
418→
419→        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
420→        let datasets = HashMap::from([(
421→            "my_table".to_string(),
422→            DatasetConfig {
423→                schema: schema.clone(),
424→            },
425→        )]);
426→
427→        let spicepod = generate_initial_spicepod(&Uuid::nil(), &setup_config, &datasets)
428→            .expect("spicepod should generate");
429→
430→        assert!(spicepod.contains("from: s3://bucket/path/my_table/"));
431→        assert!(spicepod.contains("name: my_table"));
432→        assert!(spicepod.contains("file_format: parquet"));
433→        assert!(spicepod.contains("s3_region: us-west-2"));
434→        assert!(spicepod.contains("s3_endpoint: http://localhost:9000"));
435→        assert!(spicepod.contains("engine: cayenne"));
436→        assert!(spicepod.contains("mode: file"));
437→        assert!(spicepod.contains("refresh_mode: full"));
438→        assert!(spicepod.contains("refresh_check_interval: 1s"));
439→    }
440→
441→    #[test]
442→    fn generate_spicepod_errors_on_missing_dataset_source() {
443→        let setup_config = SetupConfig {
444→            dataset_sources: HashMap::new(),
445→            etl_region: None,
446→            etl_endpoint: None,
447→        };
448→
449→        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
450→        let datasets = HashMap::from([(
451→            "missing_table".to_string(),
452→            DatasetConfig {
453→                schema: schema.clone(),
454→            },
455→        )]);
456→
457→        let err = generate_initial_spicepod(&Uuid::nil(), &setup_config, &datasets)
458→            .expect_err("missing source should fail");
459→        assert!(
460→            err.to_string().contains("missing_table"),
461→            "unexpected error: {err}"
462→        );
463→    }
464→}
