254→                .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
255→
256→        let resolved_models = component::resolve_component_references(
257→            fs,
258→            &path,
259→            &spicepod_definition.models,
260→            "model",
261→        )
262→        .await
263→        .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
264→
265→        let resolved_embeddings = component::resolve_component_references(
266→            fs,
267→            &path,
268→            &spicepod_definition.embeddings,
269→            "embeddings",
270→        )
271→        .await
272→        .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
273→
274→        let resolved_evals =
275→            component::resolve_component_references(fs, &path, &spicepod_definition.evals, "evals")
276→                .await
277→                .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
278→
279→        let resolved_tools =
280→            component::resolve_component_references(fs, &path, &spicepod_definition.tools, "tools")
281→                .await
282→                .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
283→
284→        let resolved_workers = component::resolve_component_references(
285→            fs,
286→            &path,
287→            &spicepod_definition.workers,
288→            "workers",
289→        )
290→        .await
291→        .context(UnableToResolveSpicepodComponentsSnafu { path: path.clone() })?;
292→
293→        detect_duplicate_component_names("secrets", &spicepod_definition.secrets[..])?;
294→        detect_duplicate_component_names("dataset", &resolved_datasets[..])?;
295→        detect_duplicate_component_names("view", &resolved_views[..])?;
296→        detect_duplicate_component_names("model", &resolved_models[..])?;
297→        detect_duplicate_component_names("embedding", &resolved_embeddings[..])?;
298→        detect_duplicate_component_names("eval", &resolved_evals[..])?;
299→        detect_duplicate_component_names("tool", &resolved_tools[..])?;
