317→    pub async fn load_exact(path: impl Into<PathBuf>) -> Result<Spicepod> {
318→        let fs = reader::StdFileSystem;
319→        let path = path.into();
320→        let spicepod_rdr = fs
321→            .open_exact_yaml(path.clone())
322→            .await
323→            .map_err(Box::new)
324→            .context(UnableToOpenSpicepodSnafu { path: path.clone() })?;
325→
326→        Self::load_from_rdr(&fs, spicepod_rdr, path).await
327→    }
