329→    pub async fn load_from(
330→        fs: &(impl reader::ReadableYaml + Send + Sync),
331→        path: impl Into<PathBuf>,
332→    ) -> Result<Spicepod> {
333→        let path = path.into();
334→
335→        let file_stem = path
336→            .file_stem()
337→            .map(|s| s.to_string_lossy().to_string())
338→            .unwrap_or_default();
339→
340→        let is_file = path.is_file() || path.extension().is_some();
341→
342→        let (spicepod_rdr, base_path) = if file_stem == "spicepod" && is_file {
343→            let spicepod_rdr = fs
344→                .open_exact_yaml(path.clone())
345→                .await
346→                .map_err(Box::new)
347→                .context(UnableToOpenSpicepodSnafu { path: path.clone() })?;
348→            (spicepod_rdr, path.parent().unwrap_or(Path::new(".")))
349→        } else {
350→            let spicepod_rdr = fs
351→                .open_yaml(path.clone(), "spicepod")
352→                .await
353→                .context(SpicepodNotFoundSnafu { path: path.clone() })?;
354→            (spicepod_rdr, path.as_ref())
355→        };
356→
357→        Self::load_from_rdr(fs, spicepod_rdr, base_path).await
358→    }
