 62→#[derive(Debug, Serialize)]
 63→#[cfg_attr(feature = "schemars", derive(JsonSchema))]
 64→#[serde(untagged)]
 65→pub enum ComponentOrReference<T> {
 66→    Component(T),
 67→    Reference(ComponentReference),
 68→}
 69→
 70→impl<'de, T> Deserialize<'de> for ComponentOrReference<T>
 71→where
 72→    T: Deserialize<'de> + Debug,
 73→{
 74→    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
 75→    where
 76→        D: Deserializer<'de>,
 77→    {
 78→        struct ComponentOrReferenceVisitor<T>(PhantomData<T>);
 79→
 80→        impl<'de, T> Visitor<'de> for ComponentOrReferenceVisitor<T>
 81→        where
 82→            T: Deserialize<'de> + Debug,
 83→        {
 84→            type Value = ComponentOrReference<T>;
 85→
 86→            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
 87→                formatter.write_str("a Spicepod component or component reference")
 88→            }
 89→
 90→            fn visit_map<A>(self, map: A) -> std::result::Result<Self::Value, A::Error>
 91→            where
 92→                A: de::MapAccess<'de>,
 93→            {
 94→                // Deserialize the map into a serde_value::Value
 95→                let content = Value::deserialize(de::value::MapAccessDeserializer::new(map))?;
 96→
 97→                // Try to deserialize content into T (Component)
 98→                let component_result = T::deserialize(content.clone());
 99→                match component_result {
100→                    Ok(c) => Ok(ComponentOrReference::Component(c)),
101→                    Err(component_err) => {
102→                        // Try to deserialize content into ComponentReference
103→                        let reference_result = ComponentReference::deserialize(content);
104→                        match reference_result {
105→                            Ok(r) => Ok(ComponentOrReference::Reference(r)),
106→                            Err(_) => Err(de::Error::custom(component_err.to_string())),
107→                        }
108→                    }
109→                }
110→            }
111→        }
112→
113→        deserializer.deserialize_map(ComponentOrReferenceVisitor(PhantomData))
114→    }
115→}
