117→#[derive(Debug, Snafu)]
118→pub enum Error {
119→    #[snafu(display("Unable to convert the path into a string"))]
120→    UnableToConvertPath,
121→
122→    #[snafu(display("Unable to parse spicepod component {}: {source}", path.display()))]
123→    UnableToParseSpicepodComponent { source: yaml::Error, path: PathBuf },
124→
125→    #[snafu(display("The component referenced by {} does not exist", path.display()))]
126→    InvalidComponentReference { path: PathBuf },
127→}
128→
129→pub type Result<T, E = Error> = std::result::Result<T, E>;
130→
131→pub async fn resolve_component_references<ComponentType>(
132→    fs: &(impl reader::ReadableYaml + Send + Sync),
133→    base_path: impl Into<PathBuf>,
134→    items: &[ComponentOrReference<ComponentType>],
135→    component_name: &str,
136→) -> Result<Vec<ComponentType>>
137→where
138→    ComponentType: Clone + DeserializeOwned + Debug + WithDependsOn<ComponentType>,
139→{
140→    let base_path: PathBuf = base_path.into();
141→    let futures = items
142→        .iter()
143→        .map(|item| {
144→            let value = base_path.clone();
145→            async move {
146→                match item {
147→                    ComponentOrReference::Component(component) => Ok(component.clone()),
148→                    ComponentOrReference::Reference(reference) => {
149→                        let component_base_path = value.join(&reference.r#ref);
150→
151→                        let component_rdr = fs
152→                            .open_yaml(component_base_path.clone(), component_name)
153→                            .await
154→                            .ok_or_else(|| Error::InvalidComponentReference {
155→                                path: component_base_path.clone(),
156→                            })?;
157→
158→                        let component_definition: ComponentType = yaml::from_reader(component_rdr)
159→                            .context(UnableToParseSpicepodComponentSnafu {
160→                                path: component_base_path,
161→                            })?;
162→
163→                        let component = component_definition.depends_on(&reference.depends_on);
164→
165→                        Ok(component)
166→                    }
167→                }
168→            }
169→        })
170→        .collect::<Vec<_>>();
171→
172→    futures::future::try_join_all(futures).await
173→}
