 17→use std::collections::HashMap;
 18→
 19→#[cfg(feature = "schemars")]
 20→use schemars::JsonSchema;
 21→use serde::{
 22→    Deserialize, Deserializer, Serialize,
 23→    de::{self, Unexpected},
 24→};
 25→use serde_value::Value;
 26→
 27→#[derive(Debug, Clone, Serialize, PartialEq)]
 28→#[cfg_attr(feature = "schemars", derive(JsonSchema))]
 29→#[serde(untagged)]
 30→pub enum ParamValue {
 31→    String(String),
 32→    Int(i64),
 33→    Float(f64),
 34→    Bool(bool),
 35→}
 36→
 37→impl<'de> Deserialize<'de> for ParamValue {
 38→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
 39→    where
 40→        D: Deserializer<'de>,
 41→    {
 42→        let value = Value::deserialize(deserializer)?;
 43→        match value {
 44→            Value::Bool(b) => Ok(ParamValue::Bool(b)),
 45→            Value::U8(u) => Ok(ParamValue::Int(i64::from(u))),
 46→            Value::U16(u) => Ok(ParamValue::Int(i64::from(u))),
 47→            Value::U32(u) => Ok(ParamValue::Int(i64::from(u))),
 48→            Value::U64(u) => Ok(ParamValue::Int(i64::try_from(u).map_err(|e| {
 49→                de::Error::invalid_type(Unexpected::Other(e.to_string().as_str()), &"")
 50→            })?)),
 51→            Value::I8(i) => Ok(ParamValue::Int(i64::from(i))),
 52→            Value::I16(i) => Ok(ParamValue::Int(i64::from(i))),
 53→            Value::I32(i) => Ok(ParamValue::Int(i64::from(i))),
 54→            Value::I64(i) => Ok(ParamValue::Int(i)),
 55→            Value::F32(f) => Ok(ParamValue::Float(f64::from(f))),
 56→            Value::F64(f) => Ok(ParamValue::Float(f)),
 57→            Value::Char(c) => Ok(ParamValue::String(c.to_string())),
 58→            Value::String(s) => Ok(ParamValue::String(s)),
 59→            Value::Unit => Err(de::Error::custom(
 60→                "a param value is missing for the component",
 61→            )),
 62→            Value::Option(_) => Err(de::Error::invalid_type(Unexpected::Option, &"")),
 63→            Value::Seq(_) => Err(de::Error::invalid_type(Unexpected::Seq, &"")),
 64→            Value::Map(_) => Err(de::Error::invalid_type(Unexpected::Map, &"")),
 65→            Value::Bytes(bytes) => Err(de::Error::invalid_type(Unexpected::Bytes(&bytes), &"")),
 66→            Value::Newtype(_) => Err(de::Error::invalid_type(Unexpected::Other("newtype"), &"")),
 67→        }
 68→    }
 69→}
