 74→        match self {
 75→            ParamValue::String(value) => value.clone(),
 76→            ParamValue::Int(value) => value.to_string(),
 77→            ParamValue::Float(value) => value.to_string(),
 78→            ParamValue::Bool(value) => value.to_string(),
 79→        }
 80→    }
 81→}
