                    "Dataset '{dataset_name}' is missing a 'from' URI in its config"
                ));
            }
        }
    }

    Ok(format!(
        "version: v1beta1\n\
         kind: Spicepod\n\
         name: spidapter-{short_id}\n\
         \n\
         datasets:\n{}\n",
        dataset_entries.join("\n")
    ))
}

